from layout import *
from pypdf import PdfReader
def main():
 a=load(O/'audit/baseline_counts.json');b=load(O/'outputs/release_summary.json');v=load(O/'audit/validation_report.json');m=load(O/'audit/mutation_tests.json')
 story=[P('COOKRISK','Title'),P('Stage B | Version 7','Title'),P('Clean restart release | 15 October 2026<br/>Literature evidence expansion, inherited-data audit and validation'),P('Verified outcome','Heading1'),P(f'<b>60 distinct anchors: target achieved.</b> The clean rebuild adds {b["new_anchors"]} anchors and {b["new_records"]} qualifying records to V6. Final status: <b>{v["status"]}</b>. No clinical risk score, retained-dose estimate or food-exposure calculation was produced.'),table([['Measure','Verified V6','Final V7','Change'],['Anchors',a['anchors'],b['anchors'],'+16'],['Interaction records',a['records'],b['records'],'+42'],['Distinct drug/probe labels',a['drugs'],b['drugs'],'+16'],['Primary publications, unique PMID',a['publications'],b['publications'],'+20'],['Distinct nonempty DOIs',a['unique_nonempty_doi'],b['unique_nonempty_doi'],'+18'],['Human pharmacokinetic records',64,69,'+5'],['Controlled clinical records',2,4,'+2'],['Animal records',37,50,'+13'],['In-vitro records',44,66,'+22'],['Numerical outcome records',84,97,'+13'],['Open warnings / distinct codes','17 / 16','20 / 19','+3 / +3']], [235,85,85,75]),Spacer(1,10),P('Restart and process','Heading2'),Process(),P('The interrupted 14 October V7 folder remains preserved. Its 354 supported-format files were parsed without corruption, but missing release artifacts and stale validation made it incomplete. This release uses a separate clean folder, fresh baseline counts, refreshed searches and sources, re-reviewed claims, and newly executed validation. V6 hashes match its original release manifest.'),PageBreak()]
 short={
 'Diosmetin':'Citrus flavone; diclofenac and midazolam metabolism assays (20877134, 18191104).',
 'Rutin':'Distinct citrus-peel rutinoside; florfenicol bacterial and tilapia experiments (31252064).',
 'Pterostilbene':'Berry stilbene; drug/probe metabolism and positive/null mouse anticonvulsant findings (30976185, 30877660).',
 'Ursolic acid':'Apple-peel ursane triterpene; doxorubicin and oxaliplatin experimental combinations (30572191, 27472952).',
 'Oleanolic acid':'Distinct apple-peel oleanane triterpene; aminoglycoside synergy and antibiotic nulls (26360766).',
 'Sesamin':'Sesame lignan; current S-warfarin CYP2C9 inhibition experiment (32601017).',
 'Nobiletin':'Citrus flavonoid; 5-fluorouracil cell combination (23441616).',
 'Tangeretin':'Distinct citrus flavonoid; ABCB1 drug response and contrasting midazolam metabolism (27058921, 18191104).',
 'Ascorbic acid':'Defined L-ascorbic acid/vitamin C; human indinavir PK study (15767232). Mixed master vitamin-C analytes not linked.',
 'Folic acid':'Fortified-food/supplement monoglutamate, distinct from total folate; human phenytoin PK and two clinical trials (688723, 21482950, 1828561).',
 'Phylloquinone':'Dietary vitamin K1 reference; PK/PD study in warfarin-treated patients (4091996). IV study is not a food intervention.',
 'Vanillin':'Dietary flavouring; separate tumor-cell, mouse antitumor and rat nephrotoxicity contexts (27493101).',
 'Oleuropein':'Olive constituent; breast-tumor xenograft combination with doxorubicin (28646810). Unequal comparator doses flagged.',
 'Allyl isothiocyanate':'Mustard/horseradish food additive; cisplatin cell and animal combination experiments (26396928).',
 'Zeaxanthin':'Food xanthophyll; bounded null UGT1A9/propofol result (27529203).',
 'Lutein':'Distinct food xanthophyll; trifluoperazine assay and non-SNEDDS warfarin null (27529203, 24009877).'}
 story += [P('The 16 added anchors','Heading1'),P('Each addition has a current selection date, separate food-context support, a standardized reference structure and traceable primary experimental evidence. Related entities were admitted for independently justified chemical identities and study contexts; aliases, salts and preparations were not counted as new anchors.'),table([['Anchor','Selection rationale and primary PMID(s)']]+[[n,short[n]] for n in FOODS],[110,370]),Spacer(1,9),P('Candidate pipeline','Heading2'),P('32 candidates across flavonoids, stilbenes, triterpenes, lignans, nutrients, carotenoids and other dietary bioactives were investigated. Sixty-four fresh discovery queries (32 broad and 32 historical) were capped at 100 records each, retrieving 4,805 occurrences. Sixteen candidates were selected; fourteen remain deferred and two nonspecific class/mixture names were excluded. Unreviewed discovery results are explicitly labelled. This is not an exhaustive systematic review.'),PageBreak()]
 story += [P('Evidence, nulls and inherited-data audit','Heading1'),P('Human and experimental coverage','Heading2'),P('New evidence comprises five human PK, two controlled clinical, thirteen animal and twenty-two in-vitro records. Three new records fill existing berberine and luteolin coverage gaps. Vitamin C/indinavir and folic acid/phenytoin PK studies are distinguished from randomized gingival-overgrowth trials. Folic acid prevention in children and treatment of established overgrowth in adults have different results and are not pooled as equivalent contexts.'),P('Preserved negative and context-dependent findings','Heading2'),P('Pterostilbene mouse results include drug-specific nulls alongside potentiation. Oleanolic acid antibiotic nulls and the zeaxanthin assay threshold are retained. Non-SNEDDS lutein did not significantly change warfarin exposure; the positive formulation experiment cannot be assigned to lutein alone. Its Table 3 null-arm values are now recorded with original units and precision. Vanillin tumor and nephrotoxicity experiments are represented separately.'),table([['Audit issue','V7 decision'],['V6 record preservation','All 147 evidence rows preserved exactly. Existing registry fields retained, except derived counts for berberine and luteolin.'],['Inherited extraction gaps','Six review upgrades: four berberine outcomes abstract-reverified; two bergapten-macitentan contexts selected-full-text verified. Other gaps remain visible.'],['Original-nine historical selection','Unresolved. Current rationale cannot reconstruct original triggers or dates.'],['Apigenin/rutin paclitaxel attribution','Unresolved. New isolated-rutin evidence does not repair SB-0066 preparation ambiguity.'],['Apigenin Cmax and daidzein wording','Unresolved. Prior table/prose and day/CI ambiguities retained without invented correction.'],['Daidzein/quercetin cooking provenance','Partially resolved historically; analyte/hydrolysis restrictions and uncertain master links remain. No new retention coefficient.'],['Bibliographic discrepancies','Two new Crossref/MED title differences adjudicated: omitted subtitle (1828561) and OCR-like spelling (688723); primary metadata retained.'],['New reporting limits','Sesamin prior 0.2 microM citation not assigned to current experiment; pterostilbene text/table and abstract thresholds flagged; oleuropein unequal drug doses retained.']], [150,330]),Spacer(1,8),P('Warnings remain separate from validation errors. The ledger has 20 open entries across 19 codes: 17 unresolved and three partially resolved. One prior resolved entry and two not-applicable historical targets remain as audit history.'),PageBreak()]
 story += [P('Verification, validation and delivery','Heading1'),table([['Documented outcome-review scope','V6','V7'],['Selected full-text verification',11,19],['Abstract verification',74,112],['Metadata-only in latest outcome audit',62,58],['Secondary-only new interaction claims',0,0]],[310,85,85]),Spacer(1,8),P('These are conservative latest documented review levels, not an assertion that every inherited record has been freshly re-extracted. The 42 new rows comprise six selected-full-text and 36 abstract-only extractions. XML availability alone is not full-text verification. Missing dose, sample-size, formulation or DOI detail remains explicit.'),P('Executed checks','Heading2'),P(f'V7: <b>{v["checks_passed"]}/{v["checks_total"]} checks</b>, zero errors; <b>{m["passed"]}/{m["total"]} mutation tests</b>. The checks cover IDs, structures, near-duplicates, foreign keys, bibliography, primary source paths, numerical support, study classification, nulls, separate domains, selection, inherited preservation and deterministic offline rebuilding. Numerical-token matching is a diagnostic; manual endpoint and unit review remains necessary.'),P('The existing V6 suite was run before and after expansion in an isolated copy and reported 90/90 checks and 20/20 mutation tests both times. Its implementation freshly executes 37 checks and nine mutation tests, incorporating 53 checks and eleven mutation results saved from its older V5 audit. Those historical results are not counted as newly executed V7 tests.'),P('Integrity and reproducibility','Heading2'),P('All frozen prior project files, including V6 and the interrupted attempt, are hash-checked. The final archive includes the source closure, inherited audits, inputs, scripts, search/screening logs, change logs, validation results and per-file SHA-256 manifest. No V6 evidence ID was changed, removed or recycled; new IDs run SB-0148 through SB-0189. The original 36-column interaction schema is unchanged.'),P('Known limits','Heading2'),P('The searches are capped, and many discovery records remain unreviewed. There was no independent second reviewer. Five interaction publications have no DOI supplied; PMID remains the primary identifier. Study-tested stereochemical purity is not universally specified by the reference identity. Experimental preparations and doses are not equivalent to food intake. Unique PMID counts do not establish independent cohorts. Historical cooking and selection-provenance gaps remain unresolved.'),P('Deliverables and scope','Heading2'),P('<b>stageB/release_v7_20261015_clean/</b><br/>Main tables: outputs/compound_registry.csv and outputs/stageB_food_drug_interactions_v7.csv.<br/>The README explains source paths, offline rebuilding, validation and archive verification. The full primary bibliography and source locations are in the publication and claim ledgers; food-only sources are excluded from publication counts.'),P('V6 remains unchanged. Stage A was not modified or re-evaluated. Stage C exposure estimation and Stage D scoring were not implemented. The 60-anchor target is achieved as a literature evidence resource, subject to the documented limitations.')]
 def footer(c,d):
  c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#506272'));c.drawString(48,25,'CookRisk | Stage B v7 | Clean restart | 15 October 2026');c.drawRightString(547,25,str(d.page))
 path=O/'reports/CookRisk_StageB_v7_Report.pdf';SimpleDocTemplate(str(path),pagesize=(595.28,841.89),leftMargin=48,rightMargin=48,topMargin=42,bottomMargin=48,title='CookRisk Stage B V7 - Clean Restart Release').build(story,onFirstPage=footer,onLaterPages=footer)
 pages=len(PdfReader(path).pages);print('Report pages',pages);assert pages<=5
 md=['# CookRisk Stage B V7 - clean restart','',json.dumps(b,indent=2),'','## Added anchors','']+[f'- {n}: {short[n]}' for n in FOODS]+['','## Validation','',f'{v["checks_passed"]}/{v["checks_total"]} new V7 checks and {m["passed"]}/{m["total"]} mutation tests passed. Status: {v["status"]}. V6 suite before/after results and historical-result distinction are in the PDF and README.','', 'V6 and the interrupted attempt are preserved. See the audit and provenance ledgers for unresolved issues.']
 (O/'reports/CookRisk_StageB_v7_Findings.md').write_text('\n'.join(md),encoding='utf8')
if __name__=='__main__':main()
